INSERT INTO `journal_encounter` (`Name`, `Description`, `MapX`, `MapY`, `ID`, `JournalInstanceID`, `DungeonEncounterID`, `OrderIndex`, `FirstSectionID`, `UiMapID`, `MapDisplayConditionID`, `Flags`, `DifficultyMask`, `VerifiedBuild`) VALUES
('Anub\'ikkaj', 'Anub\'ikkaj is one of Queen Ansurek\'s most brilliant tacticians. A meticulous planner known for creative use of indigenous resources. His soldiers are fanatically loyal.', 0.344258010387420654, 0.495463013648986816, 2581, 1270, 2838, 2, 28178, 2359, 127234, 0, -1, 56647),
('Chopper Redhook', 'Chopper Redhook\'s brutality is feared throughout Kul Tiras. Supported by Irontide forces, Chopper is free to rampage through Boralus, relishing the chaos rampant in the streets.', 0.57766801118850708, 0.288819998502731323, 2654, 1023, 2098, 1, 30428, 1162, 924, 2, 2, 56647),
('Master Machinists', 'Master Machinists focus on complex work at prestigious worksites. Brokk and Dorlita have worked as a team for as long as anyone can remember. Granted, Brokk\'s productivity is slipping, but both are authorized to defend their site with direct and efficient displays of violence.', 0.219530001282691955, 0.746971011161804199, 2590, 1269, 2888, 0, 28458, 2341, 0, 0, -1, 56647),
('Void Speaker Eirich', 'Eirich has been deposed, his authority seized! Overwhelmed, he fled to the innermost sanctum of the Stonevault. Yet in his machinations, he succumbed to transformation: Void energy from a malfunctioning artifact corrupts his living stone! Mystical revelations now shatter his sanity.', 0.537955999374389648, 0.754885971546173095, 2582, 1269, 2883, 4, 28202, 2341, 0, 0, -1, 56647),
('Skarmorak', 'The High Speaker spent countless years attempting to restore the Awakening Machine. One failed attempt resulted in a new horror: a golem infused with skardyn corruption. Crystals augment its elemental configuration. Though it barely communicates its alien mindset, its hatred for all creation is undeniable.', 0.802091002464294433, 0.325154006481170654, 2579, 1269, 2880, 0, 28087, 2341, 0, 0, -1, 56647),
('E.D.N.A.', 'Defense protocols engaged! Earthen Defense and Neutralization Automaton is active. Informal nomenclature: E.D.N.A. This golem has contingencies for any potential intruder. Killing skardyn is its primary directive, but any unauthorized intuder is sufficient for a lethal response.', 0.535709023475646972, 0.418289989233016967, 2572, 1269, 2854, 0, 27846, 2341, 0, 0, -1, 56647),
('Rasha\'nan', 'A winged horror from the depths of Azj-kahet. Rasha\'nan is Queen Ansurek\'s secret weapon to destroy the Arathi should her armies fail to conquer Mereldar.', 0.398422002792358398, 0.458579987287521362, 2593, 1270, 2839, 3, 28564, 2359, 127223, 0, -1, 56647);
