INSERT INTO `scene_script_text` (`ID`, `Name`, `Script`, `VerifiedBuild`) VALUES
(52729, 'Functions - Crawlers', '\nfunction SpawnCrawlers(createData, pointsID, pathID, speed, zSlush, isLeftMoving)\n\tlocal crawlers = scene:SpawnActorsAtPoints(CD_CRAWLER_A, pointsID)\n\tlocal crawler = crawlers[1]\n\t--print(#crawlers)\n\tStartCrawlerBehavior(crawler, pathID, speed, zSlush, isLeftMoving)\nend\n\nfunction AddCoroutineCrawlerEmerge(...)\n\tscene:AddCoroutineWithParams(CrawlerEmerge, ...)\nend\n\nfunction CrawlerEmerge(crawler)\n\tcrawler:PlayOneShotAnimKit(11428)\n\tWait(3)\nend\n\nfunction StartCrawlerBehavior(crawler, pathID, speed, zSlush, isLeftMoving)\n\tAddCoroutineCrawlerEmerge(crawler)\n\tlocal coinFlip = math.random(2)\n\tif coinFlip == 1 then\n\t\tcrawler:PlaySpellStateVisual(145529)\n\tend\n\tAddCoroutineCrawlerMove(crawler, pathID, speed, zSlush, isLeftMoving)\nend\n\nfunction CreateCrawlerMoveData(pathID, speed, zSlush, isLeftMoving)\n\tlocal slushHeight = zSlush or 1\n\tlocal isPathLeft = isLeftMoving or true\n\tlocal pathSpeed = speed or 14\n\tlocal path = scene:LoadPath(pathID)\n\t\n\tlocal newMoveData = MoveData:Default()\n\tnewMoveData.posControl = MovePosControl.ConstantSpeed\n\tnewMoveData.pitchControl = MoveRotControl.Tangent  \n\tnewMoveData.yawControl = MoveRotControl.Tangent\n\t--newMoveData.pitchControl = MoveRotControl.Angle \n\t--newMoveData.yawControl = MoveRotControl.Angle \n\tnewMoveData.rollControl = MoveRotControl.AngleAbs \n\tnewMoveData.teleportToFirstPoint = false\n\tnewMoveData.pathID = 0\n\tnewMoveData.speed = pathSpeed\n\tnewMoveData.teleportToFirstPoint = true\n\n\tfor i=1, #path.nodes do\n\t\tnewMoveData.points[i] = MovePoint:Default()\n\t\tif isLeftMoving then\n\t\t\tnewMoveData.points[i].roll= 270\n\t\telse\n\t\t\tnewMoveData.points[i].roll= 90\n\t\tend\n\t\tlocal randomHeightOffset = math.random(slushHeight * -1, slushHeight)\n\t\tlocal pathOffset = Vector:New(0, 0,randomHeightOffset )\n\t\tnewMoveData.points[i].pos = Vector.Add(path.nodes[i].pos, pathOffset)\n\tend\n\t\t\n\treturn newMoveData\n\nend\n\n-- Pathing\nfunction AddCoroutineCrawlerMove(...)\n\tscene:AddCoroutineWithParams(CrawlerMove, ...)\nend\n\nfunction CrawlerMove(crawler, pathID, speed, zSlush, isLeftMoving)\n\tcrawlerMoveData = CreateCrawlerMoveData(pathID, speed, zSlush, isLeftMoving)\n\tcrawler:Move(crawlerMoveData)\n\tcrawler:WaitMovementComplete()\n\tcrawler:ClearSpellVisual(145529)\n\tcrawler:StopMovement()\n\tcrawler:PlayOneShotAnimKit(19254)\n\tWait(0.75)\n\tcrawler:Fade(0, 0.25)\n\tWait(2)\n\tcrawler:Despawn()\n\nend', 56647),
