INSERT INTO `trait_sub_tree` (`Name`, `Description`, `ID`, `UiTextureAtlasElementID`, `TraitTreeID`, `VerifiedBuild`) VALUES
('Rider of the Apocalypse', 'Riders of the Apoclypse call forth the power of the legendary Four Horsemen. They can call upon the Horsemen for aid and tap into the powers of death, famine and disease.', 32, 27222, 750, 56647),
('Conduit of the Celestials', 'Conduits of the Celestials devote themselves to the teachings of the August Celestials to embody their wisdom and harness their strength. Master Conduits may briefly channel the power of all Celestials at once.', 64, 27069, 1000, 56647),
('Sunfury', 'By embracing arcane flames, Sunfury mages enhance their most devastating incantations, even calling on the aid of a spellfire phoenix.', 39, 27133, 658, 56647),
('Soul Harvester', 'Few grasp the power hidden within souls, but many know the hunger demons share for spirits of the fallen. Soul Harvesters enter pacts with demons from the Twisting Nether, serving as their host and feeding them the souls of their foes in exchange for incredible power.', 57, 27530, 720, 56647),
('Diabolist', 'The defeat of the Legion left many powerful demons unbound. Diabolists command greater demons once thought to be uncontrollable and wield abyssal powers from the Twisting Nether on the battlefield.', 59, 26935, 720, 56647);
